    function addMinter(address m) external onlyOwner {
        if (isMinter[m]) revert MinterAlreadySet();
        if (m.code.length == 0) revert MinterHasNoCode();
        if (IHashMinter(m).hashToken() != address(this)) revert MinterDisownsToken();
        isMinter[m] = true;
        unchecked {
            uint256 c = minterCount + 1;
            minterCount = c;
            emit MinterAdded(m, c);
        }
    }

    function removeMinter(address m) external onlyOwner {
        if (!isMinter[m]) revert NotMinter();
        isMinter[m] = false;
        unchecked {
            uint256 c = minterCount - 1;
            minterCount = c;
            emit MinterRemoved(m, c);
        }
    }

    function mint(address to, uint256 amount) external {
        if (!isMinter[msg.sender]) revert NotMinter();
        _mint(to, amount);
    }

    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }

    function renounceOwnership() public payable override onlyOwner {
        if (minterCount == 0) revert NoMintersYet();
        super.renounceOwnership();
    }

    function requestOwnershipHandover() public payable override {
        if (msg.value != 0) revert NoDonationsHere();
        super.requestOwnershipHandover();
    }

    function cancelOwnershipHandover() public payable override {
        if (msg.value != 0) revert NoDonationsHere();
        super.cancelOwnershipHandover();
    }
}
